"use client";

import { useEffect, useId, useState, type CSSProperties } from "react";
import { ChevronDown } from "lucide-react";
import Link from "next/link";
import {
  refreshWorkspaceAccess,
  useWorkspaceEntitlements,
} from "@/components/workspace-quota";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import styles from "./limit-banner.module.css";
import { cn } from "@/lib/utils";

const actionClass =
  "inline-flex items-center justify-center gap-1.5 min-h-11 [font-family:inherit] text-[13px] font-semibold leading-[1.3] rounded-[11px] py-[9px] px-[15px] border border-transparent cursor-pointer no-underline whitespace-nowrap";

type LimitBannerProps = {
  used: number;
  limit: number;
  resetAt: string;
  upgradeHref: string;
  allowancesHref: string;
};

export function formatResetCountdown(resetAt: string, now: number) {
  const seconds = Math.max(0, Math.ceil((Date.parse(resetAt) - now) / 1000));
  if (seconds === 0) return "Ready";
  return [
    Math.floor(seconds / 3600),
    Math.floor((seconds % 3600) / 60),
    seconds % 60,
  ]
    .map((value) => String(value).padStart(2, "0"))
    .join(":");
}

function ActiveLimitBanner({
  used,
  limit,
  resetAt,
  upgradeHref,
  allowancesHref,
}: LimitBannerProps) {
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const upgradeClass = cn(
    actionClass,
    "upgrade-shine relative isolate overflow-hidden [--button-hover-filter:none]! bg-[image:var(--primary-action-gradient)] text-[var(--primary-action-ink)] css-hover:brightness-[0.94] [@media(max-width:759px)]:flex-1",
  );
  const [open, setOpen] = useState(false);
  const [clock, setClock] = useState<{
    countdown: string;
    local: string;
  } | null>(null);
  const detailsId = useId();
  useEffect(() => {
    let refreshed = false;
    const local = new Intl.DateTimeFormat(undefined, {
      dateStyle: "medium",
      timeStyle: "short",
    }).format(new Date(resetAt));
    function tick() {
      const countdown = formatResetCountdown(resetAt, Date.now());
      setClock({ countdown, local });
      if (countdown === "Ready" && !refreshed) {
        refreshed = true;
        refreshWorkspaceAccess();
      }
    }
    tick();
    const interval = window.setInterval(tick, 1000);
    return () => window.clearInterval(interval);
  }, [resetAt]);

  return (
    <section
      role="status"
      aria-label="Daily limit reached"
      className={`${styles.banner} relative mb-5 overflow-hidden [background:var(--card)] text-foreground [border:1px_solid_var(--border)] rounded-[18px] shadow-[0_10px_30px_-14px_var(--limit-glow)] [font-family:var(--font-limit-banner),_system-ui,_sans-serif]`}
    >
      <div className="grid grid-cols-[auto_minmax(0,1fr)_auto_auto] items-center gap-5 [padding:16px_18px_16px_22px] [@media(min-width:760px)_and_(max-width:1150px)]:grid-cols-[auto_minmax(0,1fr)_auto] [@media(max-width:1150px)]:gap-y-3.5 [@media(max-width:1150px)]:gap-x-4 [@media(max-width:759px)]:grid-cols-[auto_minmax(0,1fr)]">
        <div
          className="flex flex-wrap gap-[5px] max-w-[295px] [@media(max-width:_759px)]:max-w-[min(105px,_24vw)]"
          role="img"
          aria-label={`${used} of ${limit} daily emails used`}
        >
          {Array.from({ length: limit }, (_, index) => (
            <span
              key={index}
              aria-hidden="true"
              className={`${styles.pip} w-2.5 h-8.5 rounded-[5px] [background:var(--limit-pip-off)] ${index < used ? `${styles.on} [background:var(--limit-accent)]` : ""}`}
              style={{ "--pip-delay": `${index * 0.12}s` } as CSSProperties}
            />
          ))}
        </div>
        <div className={`min-w-0`}>
          <h2 className="m-0 text-[15px] font-bold leading-[1.4]">
            Daily limit reached
          </h2>
          <p className="mt-0.5 mx-0 mb-0 text-[13px] text-muted-foreground leading-[1.45] max-w-[46ch]">
            Sent and queued emails count toward your {limit} a day. You can send
            again once the limit resets.
          </p>
        </div>
        <div
          className={`min-w-23 min-h-10 text-right leading-[1.2] [@media(max-width:_759px)]:[grid-column:2] [@media(max-width:_759px)]:text-left [@media(max-width:_759px)]:flex [@media(max-width:_759px)]:items-baseline [@media(max-width:_759px)]:gap-2 [@media(max-width:_759px)]:min-h-6`}
          aria-live="off"
        >
          {clock && (
            <>
              <b className="block text-[20px] font-semibold tabular-nums">
                {clock.countdown}
              </b>
              <small className="text-[11.5px] text-muted-foreground">
                until reset
              </small>
            </>
          )}
        </div>
        <div className="flex items-center gap-1.5 [@media(min-width:760px)_and_(max-width:1150px)]:col-[2/-1] [@media(min-width:760px)_and_(max-width:1150px)]:justify-end [@media(max-width:759px)]:col-[1/-1]">
          <button
            type="button"
            className={cn(
              actionClass,
              styles.ghost,
              "button-interaction ghost-button bg-transparent text-muted-foreground border-border",
            )}
            aria-expanded={open}
            aria-controls={detailsId}
            onClick={() => setOpen(!open)}
          >
            Details{" "}
            <ChevronDown
              size={14}
              aria-hidden="true"
              className={open ? styles.rotated : undefined}
            />
          </button>
          {access.effectivePlan === "FREE" ? (
            <button
              type="button"
              className={upgradeClass}
              onClick={(event) =>
                upgrade({ feature: "allowance", trigger: event.currentTarget })
              }
            >
              Get more sends
            </button>
          ) : (
            <Link href={upgradeHref} className={upgradeClass}>
              Get more sends
            </Link>
          )}
        </div>
      </div>
      <div
        id={detailsId}
        className={cn(
          styles.more,
          "grid",
          open ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
        )}
        inert={!open}
        aria-hidden={!open}
      >
        <div className="overflow-hidden min-h-0">
          <div
            className={` flex flex-wrap [gap:12px_28px] justify-between items-center [margin:0_18px_0_22px] [padding:14px_0_16px] border-t border-dotted border-separator text-[12.5px] text-muted-foreground [@media(max-width:_759px)]:items-start [@media(max-width:_759px)]:flex-col`}
          >
            <div>
              <span className="block mb-[3px]">Used today</span>
              <strong className="text-foreground font-semibold text-[13px]">
                {used} of {limit} emails
              </strong>
            </div>
            <div>
              <span className="block mb-[3px]">Resets</span>
              <strong className="text-foreground font-semibold text-[13px]">
                {clock ? (
                  <>
                    <time dateTime={resetAt}>{clock.local}</time>{" "}
                    <span className="text-muted-foreground font-normal">
                      (your time)
                    </span>
                  </>
                ) : (
                  "—"
                )}
              </strong>
            </div>
            <div>
              <span className="block mb-[3px]">UTC</span>
              <strong className="text-foreground font-semibold text-[13px]">
                <time dateTime={resetAt}>
                  {new Date(resetAt)
                    .toISOString()
                    .replace("T", " ")
                    .slice(0, 16)}
                </time>
              </strong>
            </div>
            <Link
              className="text-link font-semibold underline-offset-[3px] mono:text-foreground mono:underline"
              href={allowancesHref}
            >
              View allowances &amp; reset times
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}

export function LimitBanner(props: LimitBannerProps) {
  if (props.used < props.limit) return null;
  return <ActiveLimitBanner {...props} />;
}
